async function api(accion, datos = {}) {
  const cab = { "content-type": "application/json" }, cuerpo = { accion, ...datos };
  if (TOKEN) cuerpo.t = TOKEN; else { const s = (await sb.auth.getSession()).data.session; if (s) cab.authorization = "Bearer " + s.access_token; if (CUENTA) cuerpo.cuenta = CUENTA; }
  const r = await fetch(API, { method: "POST", headers: cab, body: JSON.stringify(cuerpo) }); const j = await r.json().catch(() => ({}));
  if (!r.ok) throw Object.assign(new Error(j.error || t("No se pudo completar. Inténtalo otra vez.", "It could not be completed. Please try again.")), { status: r.status, json: j });
  return j;
}
async function panel(cuerpo, otra = true) {
  if (!panelTok) panelTok = D.inicio?.panel?.token || (await api("panel_token")).token;
  const r = await fetch(API_PANEL, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ token: panelTok, v: 3, ...cuerpo }) }); const j = await r.json().catch(() => ({}));
  if (r.status === 401 && otra) { panelTok = null; return panel(cuerpo, false); }
  if (!r.ok || j.error) throw new Error(j.error || t("No se pudo completar.", "It could not be completed."));
  return j;
}
