// ============================== Datos ==============================
async function cargarPosts() { const r = await panel({ accion: "posts" }); D.posts = r.posts || []; D.cierre = r.cierre || null; return D.posts; }
const esH = (p) => p.clase === "historia";
const PEND = (p) => ["por_revisar", "ajuste"].includes(p.estado) && !p.prueba;
const OKP = (p) => ["aprobado", "programado", "publicando", "publicado"].includes(p.estado);
function semanaActual() {   // la tanda más reciente que todavía se puede revisar (o la última que hubo)
  const de = (D.posts || []).filter((p) => p.origen === "tanda" && p.lote);
  const viva = de.filter((p) => ["por_revisar", "ajuste", "aprobado", "programado", "en_reserva"].includes(p.estado)).map((p) => String(p.lote)).sort().pop();
  const lote = viva || de.map((p) => String(p.lote)).sort().pop() || null;
  const suyas = de.filter((p) => String(p.lote) === lote && p.estado !== "en_reserva");
  return { lote, posts: suyas.filter((p) => !esH(p) && p.programar_en).sort((a, b) => a.programar_en.localeCompare(b.programar_en)), hist: suyas.filter((p) => esH(p) && p.programar_en).sort((a, b) => a.programar_en.localeCompare(b.programar_en)),
    reservas: (D.posts || []).filter((p) => p.estado === "en_reserva"), publicadas: (D.posts || []).filter((p) => p.estado === "publicado" && !esH(p) && String(p.lote) !== lote).sort((a, b) => String(b.publicado_en || b.programar_en).localeCompare(String(a.publicado_en || a.programar_en))).slice(0, 9) };
}
const clase = (p) => (OKP(p) ? "ok" : p.estado === "ajuste" ? "aj" : p.estado === "en_reserva" ? "res" : "");

