async function esperarMuestras() {
  const mi = ++arrTmp.espera;
  for (let i = 0; i < 40; i++) {
    await new Promise((ok) => setTimeout(ok, i < 3 ? 2000 : 4000));
    if (mi !== arrTmp.espera || !/^#\/arranque\/4/.test(location.hash)) return;
    try { D.arr = await api(puede() ? "arranque_muestras" : "arranque"); } catch (x) { continue; }
    if ((D.arr.muestras || []).length >= 1 && !D.arr.muestras_preparando) { hito("piezas"); return pintar(); }
  }
}

