  if (I.resumen?.casos_abiertos) tarjetas.push(`<div class="proa entra"><div class="ic" aria-hidden="true">📌</div><div><b>${t(`${I.resumen.casos_abiertos} casos abiertos`, `${I.resumen.casos_abiertos} open cases`)}</b><span class="ayuda">${t("Quejas y pedidos que esperan a tu equipo.", "Complaints and requests waiting for your team.")}</span></div><a class="btn chico" href="../cuenta/#panel">${t("Ver", "See")}</a></div>`);
