    if (nombre.endsWith("/") || /(^|\/)(\.|__MACOSX)/.test(nombre) || !esImagen(nombre) || real > 12_000_000) continue;
    const ini = loc + 30 + v.getUint16(loc + 26, true) + v.getUint16(loc + 28, true), crudo = b.subarray(ini, ini + tam);
    let datos; if (met === 0) datos = crudo; else if (met === 8 && typeof DecompressionStream === "function") datos = new Uint8Array(await new Response(new Blob([crudo]).stream().pipeThrough(new DecompressionStream("deflate-raw"))).arrayBuffer()); else continue;
