  const out = []; const andar = async (e, ruta) => { if (out.length > 80) return; if (e.isFile) { const f = await new Promise((ok, mal) => e.file(ok, mal)); out.push(new File([f], ruta + f.name, { type: f.type })); } else if (e.isDirectory) { const r = e.createReader(); for (;;) { const hijos = await new Promise((ok, mal) => r.readEntries(ok, mal)); if (!hijos.length) break; for (const h of hijos) await andar(h, ruta + e.name + "/"); } } };
